const s=$('Choisir un contenu original').first().json;
const clean=value=>String(value??'').replace(/\s+/g,' ').trim();
const source=s?.source||{},title=clean(source.title),rawFacts=Array.isArray(source.facts)?source.facts:[];
const facts=rawFacts.map((raw,index)=>({raw,text:clean(raw),index})).filter(f=>f.text.length>0);
if(!title||!facts.length)throw Error('catalogue_insuffisant_pour_legendes');
const pageUrl=clean(source.url);
if(typeof source.url!=='string'||!/^https:\/\/www\.cuisine-du-cambodge\.com\/[a-z0-9][a-z0-9\/_-]*\/?$/i.test(pageUrl))throw Error('catalogue_url_invalide');
const verified=[];for(const fact of facts)if(!verified.some(item=>item.text===fact.text))verified.push(fact);
const factByText=new Map(verified.map(fact=>[fact.text,fact]));
const phrases={facebook:{openers:['Decouvrons '+title+' a partir des informations verifiees de notre catalogue.',title+' : quelques reperes issus de notre catalogue.'],closers:['Retrouvez la page associee pour consulter les details disponibles.','Poursuivez la decouverte sur la page associee.']},instagram:{openers:[title+', a decouvrir a travers les informations verifiees de notre catalogue.','Quelques reperes verifies autour de '+title+'.'],closers:['Retrouvez les details sur la page associee.','La suite est disponible sur la page associee.']}};
const contentTag=(String(source.kind||'contenu')+'_'+String(s.sourceId||'catalogue').split(':').pop()).replace(/[^a-z0-9_-]+/gi,'_');
const utm=pageUrl+'?utm_source=facebook&utm_medium=organic_social&utm_campaign=cuisine_organique&utm_content='+contentTag;
const fbPrefix=title+'\n\nDans notre catalogue Cuisine du Cambodge, les informations verifiees sont : ',fbSuffix='\n\nRetrouvez la page associee pour consulter les details disponibles.',igPrefix=title+'\n\nInformations verifiees par notre catalogue : ',igSuffix='\n\nA retrouver sur cuisine-du-cambodge.com',fbLimit=850-fbPrefix.length-fbSuffix.length-utm.length-2,igLimit=700-igPrefix.length-igSuffix.length;
const limit=Math.min(fbLimit,igLimit),fallbackUsed=[],parts=[];for(const fact of verified){const next=parts.length?parts.join(' ')+' '+fact.text:fact.text;if(next.length<=limit){parts.push(fact.text);fallbackUsed.push(fact)}}
const factText=parts.join(' '),fallbackFacebook=fbPrefix+factText+fbSuffix+'\n\n'+utm,fallbackInstagram=igPrefix+factText+igSuffix;
if(!factText||fallbackFacebook.length<200||fallbackFacebook.length>850||fallbackInstagram.length<150||fallbackInstagram.length>700)throw Error('catalogue_insuffisant_pour_legendes');
const validateCaption=(value,contract)=>{if(typeof value!=='string')return{ok:false,reason:'schema_invalide'};if(/(?:https?:\/\/|www\.|[a-z0-9-]+\.(?:com|fr|org|net)\b)/i.test(value))return{ok:false,reason:'url_interdite'};const blocks=String(value).replace(/\r/g,'').split(/\n+/).map(clean).filter(Boolean);if(blocks.length<3||!contract.openers.includes(blocks[0])||!contract.closers.includes(blocks[blocks.length-1]))return{ok:false,reason:'texte_non_verifiable'};const middle=blocks.slice(1,-1);if(!middle.length||middle.some(block=>!factByText.has(block))||new Set(middle).size!==middle.length)return{ok:false,reason:'texte_non_verifiable'};return{ok:true,text:blocks.join('\n\n'),facts:middle.map(block=>factByText.get(block))}};
const input=$input.first().json||{},raw=String(input.choices?.[0]?.message?.content??'').trim().replace(/^\x60{3}(?:json)?\s*/i,'').replace(/\s*\x60{3}$/,'');
let modelValidation='absent';
if(raw){try{const value=JSON.parse(raw),claims=value?.claimsUsed;if(!value||typeof value!=='object'||typeof value.facebookCaption!=='string'||typeof value.instagramCaption!=='string'||!Array.isArray(claims)||!claims.length)modelValidation='schema_invalide';else if(claims.some(claim=>typeof claim!=='string'||!rawFacts.includes(claim))||new Set(claims).size!==claims.length)modelValidation='preuves_non_verifiables';else{const fb=validateCaption(value.facebookCaption,phrases.facebook),ig=validateCaption(value.instagramCaption,phrases.instagram);if(!fb.ok||!ig.ok)modelValidation=!fb.ok?fb.reason:ig.reason;else{const used=[...fb.facts,...ig.facts],usedRaw=[...new Set(used.map(fact=>fact.raw))],claimSet=new Set(claims);if(usedRaw.length!==claimSet.size||usedRaw.some(fact=>!claimSet.has(fact)))modelValidation='preuves_non_verifiables';else{const facebookCaption=fb.text+'\n\n'+utm,instagramCaption=ig.text+'\n\nA retrouver sur cuisine-du-cambodge.com';if(facebookCaption.length<200||facebookCaption.length>850||instagramCaption.length<150||instagramCaption.length>700)modelValidation='plages_non_conformes';else return[{json:{...s,facebookCaption,instagramCaption,claimsUsed:usedRaw,generationMode:'ollama_borne',modelValidation:'valide_transmis'}}]}}}}catch{modelValidation='json_invalide'}}
return[{json:{...s,facebookCaption:fallbackFacebook,instagramCaption:fallbackInstagram,claimsUsed:fallbackUsed.map(fact=>fact.raw),generationMode:'catalogue_deterministe',modelValidation}}];
